  "content": "1|import React from 'react';
2|import { Check, X } from 'lucide-react';
3|import type { AppTableGridColumnDef } from './appTableGridQuery';
4|import { APP_TABLE_GRID_AUDIT_COLUMN_WIDTH } from '../ui/surfaceClasses';
5|import { MountGridDateText } from '../../app/platform/MountGridDateText';
6|
7|export type AuditRow = {
8|  createdAt?: string;
9|  createdByUsername?: string | null;
10|  createdBy?: number | null;
11|  updatedAt?: string;
12|  updatedByUsername?: string | null;
13|  updatedBy?: number | null;
14|};
15|
16|export const renderBooleanIcon = (value: boolean | null | undefined) => {
17|  if (value == null) return <span className="text-slate-300">-</span>;
18|  return value
19|    ? <Check className="h-3.5 w-3.5 text-emerald-700" aria-label="Yes" />
20|    : <X className="h-3.5 w-3.5 text-rose-700" aria-label="No" />;
21|};
22|
23|export const renderActorLabel = (username?: string | null, actorId?: number | null) => {
24|  const label = username || (actorId ? `#${actorId}` : null);
25|  if (!label) return <span className="text-slate-300">-</span>;
26|  return <span className="text-slate-600">{label}</span>;
27|};
28|
29|export function createAuditColumns<T extends AuditRow>(): AppTableGridColumnDef<T>[] {
30|  return [
31|    {
32|      id: 'created',
33|      label: 'Created',
34|      width: APP_TABLE_GRID_AUDIT_COLUMN_WIDTH,
35|      cellClassName: 'text-[11px] text-slate-600',
36|      renderCell: (row) => (
37|        <div className="flex flex-col items-start leading-tight">
38|          <MountGridDateText value={row.createdAt} />
39|          <span className="text-[10px] text-slate-400">
40|            {row.createdByUsername || (row.createdBy ? `#${row.createdBy}` : '-')}
41|          </span>
42|        </div>
43|      ),
44|      sort: false,
45|      filter: false,
46|    },
47|    {
48|      id: 'updated',
49|      label: 'Updated',
50|      width: APP_TABLE_GRID_AUDIT_COLUMN_WIDTH,
51|      cellClassName: 'text-[11px] text-slate-600',
52|      renderCell: (row) => (
53|        <div className="flex flex-col items-start leading-tight">
54|          <MountGridDateText value={row.updatedAt} />
55|          <span className="text-[10px] text-slate-400">
56|            {row.updatedByUsername || (row.updatedBy ? `#${row.updatedBy}` : '-')}
57|          </span>
58|        </div>
59|      ),
60|      sort: false,
61|      filter: false,
62|    },
63|  ];
64|}
